136: /** Title shown in the mobile app bar and used as the document title suffix. */
137: export function pageTitleFor(pathname: string, role: UserRole): string {
138:   const items = navFor(role);
139: 
140:   if (pathname === "/patients/new") return "Register woman";
141:   if (/^\/patients\/[^/]+\/visit$/.test(pathname)) return "Record ANC visit";
142:   if (/^\/patients\/[^/]+$/.test(pathname)) return "Patient record";
143: 
144:   const match = items.find((item) => isNavActive(item, pathname));
145:   return match?.label ?? "HRP Tracking";
146: }
147: 
148: /** Initials for the avatar chip. Falls back to a neutral glyph. */
149: export function initialsFor(name: string | undefined): string {
150:   if (!name) return "HW";
151:   const parts = name.trim().split(/\s+/).filter(Boolean);
152:   if (parts.length === 0) return "HW";
153:   const first = parts[0]?.[0] ?? "";
154:   const last = parts.length > 1 ? (parts[parts.length - 1]?.[0] ?? "") : "";
155:   return `${first}${last}`.toUpperCase();
156: }

