1: import type { UserRole } from "@hrp/shared";
2: import { useQuery } from "@tanstack/react-query";
3: import { api } from "./api";
4: 
5: /**
6:  * Role of the signed-in user.
7:  *
8:  * Defaults to ANM — the least-privileged role — while the session is loading or
9:  * if the request fails. A slow or broken network must never unlock supervision
10:  * tools for a field worker.
11:  */
12: export function useUserRole(): UserRole {
13:   const { data } = useQuery({
14:     queryKey: ["auth", "me"],
15:     queryFn: () => api.auth.me(),
16:     staleTime: 5 * 60 * 1000,
17:     retry: false,
18:   });
19:   return data?.role ?? "ANM";
20: }
21: 
22: /**
23:  * Whether the signed-in user may create or edit clinical records.
24:  *
25:  * Mirrors `CLINICAL_WRITE_ROLES` on the server. The server remains the
26:  * authority; this only keeps write buttons off screens where they would fail
27:  * with a 403.
28:  */
29: export function useCanWriteClinical(): boolean {
30:   const role = useUserRole();
31:   return role === "ANM" || role === "CHO";
32: }

