34: async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
35:   const headers: Record<string, string> = {
36:     ...(options.headers as Record<string, string>),
37:   };
38: 
39:   // Only send a JSON content type when there is a body. Fastify rejects an
40:   // empty body with a JSON content type, which would break DELETE and any
41:   // other bodyless request.
42:   if (options.body !== undefined && !headers["Content-Type"]) {
43:     headers["Content-Type"] = "application/json";
44:   }
45: 
46:   const token = localStorage.getItem("accessToken");
47:   if (token) headers.Authorization = `Bearer ${token}`;
48: 
49:   const response = await fetch(`${API_BASE}${path}`, {
50:     ...options,
51:     headers,
52:     credentials: "include",
53:   });
54: 
55:   if (response.status === 401) {
56:     const refreshed = await refreshToken();
57:     if (refreshed) {
58:       return request(path, options);
59:     }
60:     localStorage.clear();
61:     window.location.href = "/login";
62:     throw new ApiError(401, null, "Unauthorized");
63:   }
64: 
65:   const data = await response.json().catch(() => null);
66: 
67:   if (!response.ok) {
68:     throw new ApiError(response.status, data, data?.message ?? "Request failed");
69:   }
70: 
71:   return data as T;
72: }
