74: async function refreshToken(): Promise<boolean> {
75:   // The refresh token lives in an httpOnly cookie the browser sends
76:   // automatically. It is never read or written from JavaScript.
77:   try {
78:     const response = await fetch(`${API_BASE}/auth/refresh`, {
79:       method: "POST",
