219:     case "patient:read":
220:     case "visit:read":
221:     case "alert:read":
222:     case "queue:read":
223:     case "sync:read":
224:     case "facility:read":
225:     case "dashboard:read":
226:       return canReadFacilityScoped(actor, target);
227: 
228:     case "patient:write":
229:     case "visit:write":
230:     case "referral:create":
231:     case "sync:push":
232:       return canWriteClinical(actor, target);
233: 
234:     case "patient:archive":
235:     case "audit:read":
236:     case "admin:manage":
237:       return canAdminister(actor, target);
