113: /**
114:  * Referral visibility: an ANM only sees its own outbound referrals, while
115:  * supervisors see referrals touching either endpoint of their subtree. A
116:  * `REFERRAL_NODAL` grant widens that to either endpoint of the grant scope.
117:  */
118: export function referralVisibilityPredicate(
119:   actor: ActorScope,
120:   fromColumn: string,
121:   toColumn: string
122: ): RawBuilder<boolean> {
123:   const conditions: RawBuilder<boolean>[] = [];
124: 
125:   if (actor.role === "ANM") {
126:     conditions.push(sql<boolean>`(${sql.ref(fromColumn)} = ${actor.facilityPath})`);
127:   } else {
128:     conditions.push(pathScopePredicate(actor.facilityPath, fromColumn));
129:     conditions.push(pathScopePredicate(actor.facilityPath, toColumn));
130:   }
131: 
132:   for (const grant of actor.responsibilities) {
133:     if (grant.responsibility !== REFERRAL_NODAL) continue;
134:     conditions.push(pathScopePredicate(grant.scopePath, fromColumn));
135:     conditions.push(pathScopePredicate(grant.scopePath, toColumn));
136:   }
137: 
138:   return conditions.reduce((left, right) => sql<boolean>`(${left} OR ${right})`);
139: }
