180:       userId: user.id,
181:       role: user.role,
182:     });
183:   }
184: 
185:   if (facility.path.length === 0) {
186:     throw new AuthzError("UNKNOWN_FACILITY", "Facility has no scope path", {
187:       facilityId: facility.id,
