100:   /\.test\.(ts|tsx)$/,
101:   /\.spec\.(ts|tsx)$/,
102:   /^packages\/server\/src\/index\.ts$/,
103:   /^packages\/server\/src\/db\/(migrate|seed)\.ts$/,
104:   /^packages\/client\/src\/main\.tsx$/,
105:   /^packages\/client\/src\/utils\/sw\.ts$/,
106: ];
