113: function main() {
114:   const changedLines = getChangedLines();
115:   const coverage = readLcovFiles();
116: 
117:   // Repo-relative path -> line -> hit count
118:   const byRepoPath = new Map();
119:   for (const [absolutePath, lineMap] of coverage) {
120:     byRepoPath.set(toRepoPath(absolutePath), lineMap);
121:   }
122: 
123:   let totalChanged = 0;
124:   let coveredChanged = 0;
125:   const uncovered = [];
126:   const filesWithoutCoverage = [];
127:   const perFile = [];
128: 
129:   for (const [file, lines] of changedLines) {
130:     if (isExcluded(file)) continue;
131: 
132:     const cov = byRepoPath.get(file);
133:     if (!cov) {
134:       // No coverage data for this file. Report it so a new untested module is
135:       // visible instead of silently skipped.
136:       if (/\.(ts|tsx)$/.test(file)) {
137:         filesWithoutCoverage.push(file);
138:       }
139:       continue;
140:     }
141: 
142:     let fileHits = 0;
143:     for (const line of lines) {
144:       const hits = cov.get(line);
145:       // Lines that never appear in the lcov data are not executable (comments,
146:       // blank lines, type-only declarations). Counting them would make the bar
147:       // impossible to reach for any change that adds documentation.
148:       if (hits === undefined) continue;
149: 
150:       totalChanged += 1;
151:       if (hits > 0) {
