import type {
  CreatePatient,
  CreateReferral,
  CreateStaff,
  CreateVisit,
  DispatchFollowUp,
  Facility,
  FollowUpFilter,
  FollowUpListItem,
  Login,
  Pagination,
  Patient,
  PatientFilter,
  Referral,
  StaffMember,
  SupervisionAlert,
  SupervisionFilter,
  SyncPayload,
  SyncQueue,
  SyncResponse,
  UpdateFollowUp,
  User,
  Visit,
  VisitFilter,
} from "@hrp/shared";

const API_BASE = import.meta.env.VITE_API_URL ?? "/api";

class ApiError extends Error {
  constructor(
    public status: number,
    public data: unknown,
    message: string
  ) {
    super(message);
    this.name = "ApiError";
  }
}

function toSearch(params?: Record<string, unknown>): string {
  const search = new URLSearchParams();
  if (params)
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined) search.set(k, String(v));
    }
  return search.toString();
}

async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string>),
  };

  // Only send a JSON content type when there is a body. Fastify rejects an
  // empty body with a JSON content type, which would break DELETE and any
  // other bodyless request.
  if (options.body !== undefined && !headers["Content-Type"]) {
    headers["Content-Type"] = "application/json";
  }

  const token = localStorage.getItem("accessToken");
  if (token) headers.Authorization = `Bearer ${token}`;

  const response = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers,
    credentials: "include",
  });

  if (response.status === 401) {
    const refreshed = await refreshToken();
    if (refreshed) {
      return request(path, options);
    }
    localStorage.clear();
    window.location.href = "/login";
    throw new ApiError(401, null, "Unauthorized");
  }

  const data = await response.json().catch(() => null);

  if (!response.ok) {
    throw new ApiError(response.status, data, data?.message ?? "Request failed");
  }

  return data as T;
}

async function refreshToken(): Promise<boolean> {
  // The refresh token lives in an httpOnly cookie the browser sends
  // automatically. It is never read or written from JavaScript.
  try {
    const response = await fetch(`${API_BASE}/auth/refresh`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
    });

    if (response.ok) {
      const data = await response.json();
      if (data.accessToken) {
        localStorage.setItem("accessToken", data.accessToken);
        return true;
      }
    }
  } catch {
    // Network failure during refresh is treated as "not refreshed".
  }
  return false;
}

export const api = {
  auth: {
    login: (data: Login) =>
      request<{ accessToken: string; user: User }>("/auth/login", {
        method: "POST",
        body: JSON.stringify(data),
      }),
    refresh: () => request<{ accessToken: string }>("/auth/refresh", { method: "POST" }),
    me: () => request<User>("/auth/me"),
    logout: () => request<void>("/auth/logout", { method: "POST" }),
  },

  patients: {
    list: (params?: PatientFilter & Pagination) => {
      const search = new URLSearchParams();
      if (params)
        for (const [k, v] of Object.entries(params)) {
          if (v !== undefined) search.set(k, String(v));
        }
      return request<{ data: Patient[]; total: number; page: number; limit: number }>(
        `/patients?${search}`
      );
    },
    get: (id: string) => request<Patient>(`/patients/${id}`),
    create: (data: CreatePatient) =>
      request<Patient>("/patients", { method: "POST", body: JSON.stringify(data) }),
    update: (id: string, data: Partial<CreatePatient>) =>
      request<Patient>(`/patients/${id}`, { method: "PATCH", body: JSON.stringify(data) }),
    delete: (id: string) => request<void>(`/patients/${id}`, { method: "DELETE" }),
  },

  /**
   * HRP-specific endpoints. These carry the complication, follow-up track and
   * the joined attribution the block line list shows.
   */
  hrp: {
    patients: {
      list: (params?: PatientFilter & Pagination & Record<string, unknown>) =>
        request<{ data: Patient[]; total: number; page: number; limit: number }>(
          `/hrp/patients?${toSearch(params)}`
        ),
      get: (id: string) => request<Patient>(`/hrp/patients/${id}`),
      create: (data: CreatePatient) =>
        request<Patient>("/hrp/patients", { method: "POST", body: JSON.stringify(data) }),
      update: (id: string, data: Partial<CreatePatient>) =>
        request<Patient>(`/hrp/patients/${id}`, {
          method: "PATCH",
          body: JSON.stringify(data),
        }),
    },
    followUps: {
      list: (params?: FollowUpFilter & Pagination & { search?: string }) =>
        request<{ data: FollowUpListItem[]; total: number; page: number; limit: number }>(
          `/hrp/follow-ups?${toSearch(params)}`
        ),
      field: () =>
        request<{
          data: FollowUpListItem[];
          total: number;
          page: number;
          limit: number;
          active: boolean;
        }>("/hrp/follow-ups/field"),
      panel: () => request<{ data: FollowUpListItem[] }>("/hrp/follow-ups/panel"),
      update: (id: string, data: UpdateFollowUp) =>
        request<FollowUpListItem>(`/hrp/follow-ups/${id}`, {
          method: "PATCH",
          body: JSON.stringify(data),
        }),
      dispatch: (data: DispatchFollowUp) =>
        request<{ data: FollowUpListItem[]; count: number }>("/hrp/follow-ups/dispatch", {
          method: "POST",
          body: JSON.stringify(data),
        }),
    },
  },

  staff: {
    list: () => request<{ data: StaffMember[]; total: number }>("/staff"),
    create: (data: CreateStaff) =>
      request<StaffMember>("/staff", { method: "POST", body: JSON.stringify(data) }),
    deactivate: (id: string) =>
      request<{ id: string; isActive: boolean }>(`/staff/${id}/deactivate`, { method: "PATCH" }),
  },

  visits: {
    list: (params?: VisitFilter & Pagination) => {
      const search = new URLSearchParams();
      if (params)
        for (const [k, v] of Object.entries(params)) {
          if (v !== undefined) search.set(k, String(v));
        }
      return request<{ data: Visit[]; total: number; page: number; limit: number }>(
        `/visits?${search}`
      );
    },
    get: (id: string) => request<Visit>(`/visits/${id}`),
    create: (data: CreateVisit) =>
      request<Visit>("/visits", { method: "POST", body: JSON.stringify(data) }),
    update: (id: string, data: Partial<CreateVisit>) =>
      request<Visit>(`/visits/${id}`, { method: "PATCH", body: JSON.stringify(data) }),
    byPatient: (patientId: string) => request<Visit[]>(`/visits/by-patient/${patientId}`),
  },

  referrals: {
    list: (params?: Pagination) => {
      const search = new URLSearchParams();
      if (params)
        for (const [k, v] of Object.entries(params)) {
          if (v !== undefined) search.set(k, String(v));
        }
      return request<{ data: Referral[]; total: number }>(`/referrals?${search}`);
    },
    create: (data: CreateReferral) =>
      request<Referral>("/referrals", { method: "POST", body: JSON.stringify(data) }),
    update: (id: string, data: Partial<Referral>) =>
      request<Referral>(`/referrals/${id}`, { method: "PATCH", body: JSON.stringify(data) }),
  },

  facilities: {
    list: () => request<Facility[]>("/facilities"),
    get: (id: string) => request<Facility>(`/facilities/${id}`),
    children: (id: string) => request<Facility[]>(`/facilities/${id}/children`),
  },

  sync: {
    push: (payload: SyncPayload) =>
      request<SyncResponse>("/sync/push", { method: "POST", body: JSON.stringify(payload) }),
    pull: (since?: Date) => {
      const search = since ? `?since=${since.toISOString()}` : "";
      return request<SyncResponse>(`/sync/pull${search}`);
    },
  },

  supervision: {
    alerts: (params?: SupervisionFilter & Pagination) => {
      const search = new URLSearchParams();
      if (params)
        for (const [k, v] of Object.entries(params)) {
          if (v !== undefined) search.set(k, String(v));
        }
      return request<{ data: SupervisionAlert[]; total: number }>(`/supervision/alerts?${search}`);
    },
    acknowledge: (id: string) =>
      request<SupervisionAlert>(`/supervision/alerts/${id}/acknowledge`, { method: "POST" }),
  },

  queue: {
    list: () => request<SyncQueue[]>("/queue"),
    retry: (id: string) => request<SyncQueue>(`/queue/${id}/retry`, { method: "POST" }),
  },
};

export { ApiError };

import type { UserRole } from "@hrp/shared";
import type { ComponentType } from "react";
import {
  ActivityIcon,
  ArrowRightIcon,
  BellIcon,
  CalendarIcon,
  CogIcon,
  HomeIcon,
  ListChecksIcon,
  UserPlusIcon,
  UsersIcon,
} from "../components/ui/Icons";

export type NavSection = "Field work" | "Oversight" | "Account";

export interface NavItem {
  path: string;
  label: string;
  /** Shorter label for the four-item mobile tab bar. */
  shortLabel: string;
  icon: ComponentType<{ className?: string }>;
  section: NavSection;
}

/** ANM and CHO work the field app: register, triage, follow up. */
export function isFieldRole(role: UserRole): boolean {
  return role === "ANM" || role === "CHO";
}

/** Block and district staff work the oversight app. */
export function isNodalRole(role: UserRole): boolean {
  return role === "BHM" || role === "DHS";
}

const addCase: NavItem = {
  path: "/",
  label: "Add case",
  shortLabel: "Add",
  icon: UserPlusIcon,
  section: "Field work",
};

const dashboard: NavItem = {
  path: "/dashboard",
  label: "Dashboard",
  shortLabel: "Home",
  icon: HomeIcon,
  section: "Field work",
};

const fieldFollowUps: NavItem = {
  path: "/follow-ups",
  label: "Follow-ups",
  shortLabel: "Follow-ups",
  icon: CalendarIcon,
  section: "Field work",
};

const patients: NavItem = {
  path: "/patients",
  label: "Patients",
  shortLabel: "Patients",
  icon: UsersIcon,
  section: "Field work",
};

const blockDashboard: NavItem = {
  path: "/",
  label: "Block dashboard",
  shortLabel: "Dashboard",
  icon: ActivityIcon,
  section: "Oversight",
};

const blockFollowUps: NavItem = {
  path: "/follow-ups",
  label: "Follow-up to be done",
  shortLabel: "Follow-ups",
  icon: ListChecksIcon,
  section: "Oversight",
};

const hrpIntake: NavItem = {
  path: "/patients/new",
  label: "Add HRP case",
  shortLabel: "Add",
  icon: UserPlusIcon,
  section: "Oversight",
};

const team: NavItem = {
  path: "/team",
  label: "Team & access",
  shortLabel: "Team",
  icon: UsersIcon,
  section: "Account",
};

const referrals: NavItem = {
  path: "/referrals",
  label: "Referrals",
  shortLabel: "Referrals",
  icon: ArrowRightIcon,
  section: "Oversight",
};

const supervision: NavItem = {
  path: "/supervision",
  label: "Supervision",
  shortLabel: "Supervision",
  icon: BellIcon,
  section: "Oversight",
};

const settings: NavItem = {
  path: "/settings",
  label: "Settings",
  shortLabel: "Settings",
  icon: CogIcon,
  section: "Account",
};

const NAV_BY_ROLE: Record<UserRole, NavItem[]> = {
  // Field app, in the order a field worker uses it: register first, then the
  // triage dashboard, then the assigned follow-up list.
  ANM: [addCase, dashboard, fieldFollowUps, patients, referrals, settings],
  CHO: [addCase, dashboard, fieldFollowUps, patients, referrals, supervision, settings],

  // Oversight app: block-wide surveillance, the shared line list, helpdesk
  // intake, and the screen that provisions helpdesk credentials.
  BHM: [
    blockDashboard,
    blockFollowUps,
    hrpIntake,
    team,
    { ...patients, section: "Oversight", label: "All people" },
    referrals,
    supervision,
    settings,
  ],
  DHS: [
    blockDashboard,
    blockFollowUps,
    hrpIntake,
    team,
    { ...patients, section: "Oversight", label: "All people" },
    referrals,
    supervision,
    settings,
  ],
  HELPDESK: [
    blockDashboard,
    blockFollowUps,
    hrpIntake,
    { ...patients, section: "Oversight", label: "All people" },
    settings,
  ],
};

export function navFor(role: UserRole): NavItem[] {
  return NAV_BY_ROLE[role];
}

/** The three destinations that fit in the mobile tab bar, plus "More". */
export function mobileTabsFor(role: UserRole): NavItem[] {
  return navFor(role).slice(0, 3);
}

/** Destinations that only appear in the mobile "More" sheet. */
export function mobileOverflowFor(role: UserRole): NavItem[] {
  return navFor(role).slice(3);
}

/** True when the nav item should be highlighted for the current path. */
export function isNavActive(item: NavItem, pathname: string): boolean {
  if (item.path === "/") return pathname === "/";
  return pathname === item.path || pathname.startsWith(`${item.path}/`);
}

/** Title shown in the mobile app bar and used as the document title suffix. */
export function pageTitleFor(pathname: string, role: UserRole): string {
  const items = navFor(role);

  if (pathname === "/patients/new") return "Add HRP case";
  if (/^\/patients\/[^/]+\/visit$/.test(pathname)) return "Record ANC visit";
  if (/^\/patients\/[^/]+$/.test(pathname)) return "Patient record";

  const match = items.find((item) => isNavActive(item, pathname));
  return match?.label ?? "HRP Tracking";
}

/** Initials for the avatar chip. Falls back to a neutral glyph. */
export function initialsFor(name: string | undefined): string {
  if (!name) return "HW";
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "HW";
  const first = parts[0]?.[0] ?? "";
  const last = parts.length > 1 ? (parts[parts.length - 1]?.[0] ?? "") : "";
  return `${first}${last}`.toUpperCase();
}

import type { UserRole } from "@hrp/shared";
import { useQuery } from "@tanstack/react-query";
import { api } from "./api";
import { isFieldRole, isNodalRole } from "./nav";

/**
 * Role of the signed-in user.
 *
 * Defaults to ANM — the least-privileged role — while the session is loading or
 * if the request fails. A slow or broken network must never unlock supervision
 * tools for a field worker.
 */
export function useUserRole(): UserRole {
  const { data } = useQuery({
    queryKey: ["auth", "me"],
    queryFn: () => api.auth.me(),
    staleTime: 5 * 60 * 1000,
    retry: false,
  });
  return data?.role ?? "ANM";
}

/**
 * Whether the signed-in user may create or edit clinical records.
 *
 * Mirrors `CLINICAL_WRITE_ROLES` on the server. The server remains the
 * authority; this only keeps write buttons off screens where they would fail
 * with a 403.
 */
export function useCanWriteClinical(): boolean {
  const role = useUserRole();
  return role === "ANM" || role === "CHO" || role === "HELPDESK";
}

/** True when the current role uses the field (mobile-first) app. */
export function useIsFieldRole(): boolean {
  return isFieldRole(useUserRole());
}

/** True when the current role uses the block/district oversight app. */
export function useIsNodalRole(): boolean {
  return isNodalRole(useUserRole());
}

export const ROLE_LABEL: Record<UserRole, string> = {
  ANM: "ANM · field worker",
  CHO: "CHO · facility",
  BHM: "Block nodal officer",
  DHS: "District officer",
  HELPDESK: "HRP Helpdesk",
};

/** Short tier label used in attribution text, e.g. "Done by ANM". */
export const ROLE_TIER_LABEL: Record<UserRole, string> = {
  ANM: "ANM",
  CHO: "CHO",
  BHM: "Block Nodal",
  DHS: "District Nodal",
  HELPDESK: "HRP_Helpdesk",
};

export function tierLabel(role: string | null | undefined): string {
  if (!role) return "Field team";
  return ROLE_TIER_LABEL[role as UserRole] ?? "Field team";
}

