import {
  type HrpComplication,
  type HrpFollowUpStatus,
  type HrpFollowUpTrack,
  type Patient,
  type RiskLevel,
  getNextPmsmaDate,
  inferHrpTrack,
} from "@hrp/shared";
import type { FollowUpListItem } from "@hrp/shared/schemas";

const DAY_MS = 24 * 60 * 60 * 1000;

export function startOfToday(now: Date = new Date()): Date {
  return new Date(now.getFullYear(), now.getMonth(), now.getDate());
}

/** The expected date of delivery is LMP + 280 days. */
export function eddFromLmp(lmp: Date): Date {
  const edd = new Date(lmp.getFullYear(), lmp.getMonth(), lmp.getDate());
  edd.setDate(edd.getDate() + 280);
  return edd;
}

export interface GestationalAge {
  weeks: number;
  days: number;
  totalDays: number;
}

/** Completed weeks and days between LMP and today. */
export function gestationalAge(lmp: Date, at: Date = new Date()): GestationalAge {
  const from = new Date(lmp.getFullYear(), lmp.getMonth(), lmp.getDate());
  const to = new Date(at.getFullYear(), at.getMonth(), at.getDate());
  const totalDays = Math.max(0, Math.round((to.getTime() - from.getTime()) / DAY_MS));
  return { weeks: Math.floor(totalDays / 7), days: totalDays % 7, totalDays };
}

export function gestationalAgeLabel(lmp: Date, at: Date = new Date()): string {
  const { weeks, days } = gestationalAge(lmp, at);
  return `${weeks}w ${days}d`;
}

/**
 * A single woman on the follow-up line list.
 *
 * The row is assembled from a server follow-up record when one exists, and
 * otherwise from the patient's own track/schedule so a newly registered woman
 * never disappears from the panel.
 */
export interface FollowUpRow {
  key: string;
  patientId: string;
  followUpId: string | null;
  patientName: string;
  age: number;
  phone: string | null;
  ashaPhone: string | null;
  village: string | null;
  complication: HrpComplication | null;
  riskLevel: RiskLevel;
  track: HrpFollowUpTrack;
  status: HrpFollowUpStatus;
  scheduledDate: Date;
  assignedToName: string | null;
  assignedToRole: string | null;
  completedByName: string | null;
  completedByRole: string | null;
  notes: string | null;
}

const STATUS_ORDER: Record<HrpFollowUpStatus, number> = {
  PENDING: 0,
  NOT_REACHABLE: 1,
  COMPLETE: 2,
};

const ACTIVE_STATUSES: ReadonlySet<HrpFollowUpStatus> = new Set(["PENDING", "NOT_REACHABLE"]);

function defaultScheduledDate(track: HrpFollowUpTrack, village: string | null, now: Date): Date {
  if (track === "IMMEDIATE_7_DAYS") return new Date(now.getTime() + 7 * DAY_MS);
  if (track === "PMSMA_SESSION") return getNextPmsmaDate(now);
  return new Date(now.getTime() + 30 * DAY_MS);
}

/** Picks the row that represents a woman's current contact. */
function pickRecord(records: FollowUpListItem[]): FollowUpListItem | undefined {
  if (records.length === 0) return undefined;
  const sorted = [...records].sort(
    (a, b) => new Date(a.scheduledDate).getTime() - new Date(b.scheduledDate).getTime()
  );
  const active = sorted.find((record) => ACTIVE_STATUSES.has(record.status));
  return active ?? sorted[sorted.length - 1];
}

/**
 * Merge the server line list with the patient register.
 *
 * One row per woman: the active follow-up record wins, then her own scheduled
 * track, then the track inferred from referral and risk level.
 */
export function buildFollowUpLineList(
  patients: Patient[],
  records: FollowUpListItem[],
  now: Date = new Date()
): FollowUpRow[] {
  const recordsByPatient = new Map<string, FollowUpListItem[]>();
  for (const record of records) {
    const list = recordsByPatient.get(record.patientId) ?? [];
    list.push(record);
    recordsByPatient.set(record.patientId, list);
  }

  const patientById = new Map(patients.map((patient) => [patient.id, patient]));

  // Include a record whose patient is outside the first page of the register,
  // otherwise a long block list silently drops rows.
  const patientIds = new Set([...patientById.keys(), ...recordsByPatient.keys()]);

  const rows: FollowUpRow[] = [];
  for (const patientId of patientIds) {
    const patient = patientById.get(patientId);
    const record = pickRecord(recordsByPatient.get(patientId) ?? []);

    const track =
      record?.track ??
      patient?.followUpTrack ??
      inferHrpTrack({ referred: patient?.referred, riskLevel: patient?.riskLevel });
    const scheduledDate = record
      ? new Date(record.scheduledDate)
      : patient?.followUpScheduledDate
        ? new Date(patient.followUpScheduledDate)
        : defaultScheduledDate(track, record?.village ?? null, now);

    rows.push({
      key: record ? `follow-up-${record.id}` : `patient-${patientId}`,
      patientId,
      followUpId: record?.id ?? null,
      patientName: record?.patientName ?? patient?.name ?? "Unknown woman",
      age: record?.patientAge ?? patient?.age ?? 0,
      phone: record?.patientPhone ?? patient?.phone ?? null,
      ashaPhone: patient?.ashaPhone ?? null,
      village: record?.village ?? patient?.address ?? null,
      complication: record?.hrpComplication ?? patient?.hrpComplication ?? null,
      riskLevel: record?.patientRiskLevel ?? patient?.riskLevel ?? "GREEN",
      track,
      status: record?.status ?? patient?.followUpStatus ?? "PENDING",
      scheduledDate,
      assignedToName: record?.assignedToName ?? null,
      assignedToRole: record?.assignedToRole ?? null,
      completedByName: record?.completedByName ?? null,
      completedByRole: record?.completedByRole ?? null,
      notes: record?.notes ?? null,
    });
  }

  return rows.sort(
    (a, b) =>
      STATUS_ORDER[a.status] - STATUS_ORDER[b.status] ||
      a.scheduledDate.getTime() - b.scheduledDate.getTime() ||
      a.patientName.localeCompare(b.patientName)
  );
}

export function isBreached(row: FollowUpRow, now: Date = new Date()): boolean {
  return row.status === "PENDING" && row.scheduledDate.getTime() < startOfToday(now).getTime();
}

export interface TrackSummary {
  total: number;
  pending: number;
  complete: number;
  notReachable: number;
  breached: number;
}

export interface FollowUpSummary {
  total: number;
  pending: number;
  complete: number;
  notReachable: number;
  breached: number;
  complianceRate: number;
  nextPmsmaDate: Date;
  pmsmaCohort: number;
  byTrack: Record<HrpFollowUpTrack, TrackSummary>;
}

function emptyTrack(): TrackSummary {
  return { total: 0, pending: 0, complete: 0, notReachable: 0, breached: 0 };
}

/**
 * Block dashboard counters. Everything is derived from the same line list the
 * panel renders, so the tiles and the table can never disagree.
 */
export function summariseFollowUps(
  rows: FollowUpRow[],
  now: Date = new Date()
): FollowUpSummary {
  const byTrack: Record<HrpFollowUpTrack, TrackSummary> = {
    IMMEDIATE_7_DAYS: emptyTrack(),
    PMSMA_SESSION: emptyTrack(),
    VHSND_COMMUNITY: emptyTrack(),
  };

  let pending = 0;
  let complete = 0;
  let notReachable = 0;
  let breached = 0;

  for (const row of rows) {
    const track = byTrack[row.track];
    track.total += 1;

    if (row.status === "PENDING") {
      pending += 1;
      track.pending += 1;
      if (isBreached(row, now)) {
        breached += 1;
        track.breached += 1;
      }
    } else if (row.status === "COMPLETE") {
      complete += 1;
      track.complete += 1;
    } else {
      notReachable += 1;
      track.notReachable += 1;
    }
  }

  const total = rows.length;
  return {
    total,
    pending,
    complete,
    notReachable,
    breached,
    complianceRate: total === 0 ? 0 : Math.round((complete / total) * 100),
    nextPmsmaDate: getNextPmsmaDate(now),
    pmsmaCohort: byTrack.PMSMA_SESSION.total,
    byTrack,
  };
}

/** Attribution copy used by the block's shared line list. */
export function attributionLabel(row: FollowUpRow): string {
  if (row.completedByName) {
    const tier = row.completedByRole ? humanTier(row.completedByRole) : "field team";
    return `Done by ${tier} (${row.completedByName})`;
  }
  if (row.assignedToName) {
    const tier = row.assignedToRole ? humanTier(row.assignedToRole) : "field team";
    return `Assigned to ${tier} (${row.assignedToName})`;
  }
  return "Unassigned / Pending field outreach";
}

function humanTier(role: string): string {
  if (role === "HELPDESK") return "HRP_Helpdesk";
  if (role === "BHM") return "Block Nodal";
  if (role === "DHS") return "District Nodal";
  return role;
}

/** "15 Oct" style label for the next PMSMA cohort tile. */
export function formatShortDate(date: Date): string {
  return date.toLocaleDateString("en-IN", { day: "numeric", month: "short" });
}

import {
  type CreatePatient,
  type HrpComplication,
  HRP_COMPLICATIONS,
  hrpReasonForComplication,
} from "@hrp/shared";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import { useMemo, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { FormField, Select } from "../components/ui";
import {
  ArrowLeftIcon,
  CalendarIcon,
  ClipboardIcon,
  MapPinIcon,
  PhoneIcon,
  UserPlusIcon,
} from "../components/ui/Icons";
import { PageHeader } from "../components/ui/PageHeader";
import { Panel, PanelBody, PanelHeader } from "../components/ui/Panel";
import { api } from "../lib/api";
import { eddFromLmp, gestationalAgeLabel } from "../lib/hrp";
import { useUserRole } from "../lib/session";

interface FormState {
  name: string;
  phone: string;
  age: string;
  villageId: string;
  lmp: string;
  complication: HrpComplication | "";
  referred: boolean;
}

const INITIAL_FORM: FormState = {
  name: "",
  phone: "",
  age: "",
  villageId: "",
  lmp: "",
  complication: "",
  referred: false,
};

const COMPLICATION_OPTIONS = HRP_COMPLICATIONS.map((option) => ({
  value: option.value,
  label: option.label,
}));

const VILLAGE_LEVELS = new Set(["VILLAGE", "HSC", "HWC"]);

export default function AddPatientPage() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const role = useUserRole();
  const [form, setForm] = useState<FormState>(INITIAL_FORM);
  const [errors, setErrors] = useState<Partial<Record<keyof FormState, string>>>({});

  const { data: facilities } = useQuery({
    queryKey: ["facilities"],
    queryFn: () => api.facilities.list(),
    staleTime: 10 * 60 * 1000,
    retry: false,
  });

  const villageOptions = useMemo(() => {
    const list = Array.isArray(facilities) ? facilities : [];
    return list
      .filter((facility) => VILLAGE_LEVELS.has(facility.level))
      .map((facility) => ({ value: facility.id, label: facility.name }))
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [facilities]);

  const createMutation = useMutation({
    mutationFn: (data: CreatePatient) => api.hrp.patients.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patients"] });
      queryClient.invalidateQueries({ queryKey: ["hrp", "patients"] });
      queryClient.invalidateQueries({ queryKey: ["hrp", "follow-ups"] });
      navigate("/follow-ups");
    },
  });

  const update = <K extends keyof FormState>(field: K, value: FormState[K]) => {
    setForm((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  };

  const lmpDate = form.lmp ? new Date(`${form.lmp}T00:00:00`) : null;
  const validLmp = lmpDate && !Number.isNaN(lmpDate.getTime()) ? lmpDate : null;
  const edd = validLmp ? eddFromLmp(validLmp) : null;

  const validate = (): boolean => {
    const next: Partial<Record<keyof FormState, string>> = {};
    if (!form.name.trim()) next.name = "Enter the mother's full name";

    const phoneDigits = form.phone.replace(/\D/g, "");
    if (!phoneDigits) next.phone = "Enter her 10-digit mobile number";
    else if (phoneDigits.length !== 10) next.phone = "Enter a 10-digit mobile number";

    const age = Number(form.age);
    if (!form.age.trim() || Number.isNaN(age) || !Number.isInteger(age)) {
      next.age = "Enter her age in completed years";
    } else if (age < 15 || age > 55) {
      next.age = "Age must be between 15 and 55";
    }

    if (villageOptions.length > 0 && !form.villageId) next.villageId = "Select the village / HWC";
    if (!validLmp) next.lmp = "Enter the last menstrual period date";
    else if (validLmp.getTime() > Date.now()) next.lmp = "LMP cannot be in the future";
    if (!form.complication) next.complication = "Select the HRP complication";

    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!validate() || !validLmp || !form.complication) return;

    const villageName = villageOptions.find((option) => option.value === form.villageId)?.label;

    createMutation.mutate({
      name: form.name.trim(),
      age: Number(form.age),
      phone: form.phone.replace(/\D/g, ""),
      address: villageName ?? null,
      hrpComplication: form.complication,
      hrpReason: hrpReasonForComplication(form.complication),
      isHrp: true,
      referred: form.referred,
      lmp: validLmp,
      edd: eddFromLmp(validLmp),
      ashaName: null,
      ashaPhone: null,
      gravida: 0,
      para: 0,
      abortions: 0,
      riskFactors: [],
    });
  };

  const title = role === "HELPDESK" || role === "BHM" || role === "DHS" ? "Add HRP case" : "Add case";

  return (
    <div className="space-y-5">
      <PageHeader
        eyebrow="HRP intake"
        title={title}
        description="Seven fields. The three-track follow-up schedule is calculated automatically."
        actions={
          <Link to="/" className="btn btn-secondary">
            <ArrowLeftIcon className="h-4 w-4" />
            Back
          </Link>
        }
      />

      {createMutation.isError && (
        <div
          className="rounded border border-triage-red-line bg-triage-red-bg px-4 py-3"
          role="alert"
          aria-live="polite"
        >
          <p className="text-sm font-medium text-triage-red">
            Could not save the registration. Check the details and try again.
          </p>
        </div>
      )}

      <form onSubmit={handleSubmit} className="grid gap-4 lg:grid-cols-3">
        <div className="space-y-4 lg:col-span-2">
          <Panel>
            <PanelHeader
              title="Woman and household"
              description="As written on the MCP card / Aadhaar"
              action={<UserPlusIcon className="h-4 w-4 text-ink-subtle" />}
            />
            <PanelBody className="grid gap-4 sm:grid-cols-2">
              <div className="sm:col-span-2">
                <FormField
                  label="Mother's full name"
                  id="patient-name"
                  required
                  error={errors.name}
                  hint="Match the name on the MCP card or Aadhaar"
                >
                  <input
                    type="text"
                    autoComplete="name"
                    value={form.name}
                    onChange={(e) => update("name", e.target.value)}
                    placeholder="Full name"
                  />
                </FormField>
              </div>

              <div className="space-y-1.5">
                <label htmlFor="patient-phone" className="label">
                  Mobile number
                  <span className="ml-0.5 text-triage-red-solid" aria-hidden="true">
                    *
                  </span>
                </label>
                <div className="flex">
                  <span
                    aria-hidden="true"
                    className="inline-flex items-center rounded-l border border-r-0 border-line-strong bg-canvas px-3 text-sm text-ink-muted"
                  >
                    +91
                  </span>
                  <input
                    id="patient-phone"
                    type="tel"
                    inputMode="numeric"
                    autoComplete="tel-national"
                    className={`input rounded-l-none ${errors.phone ? "input-error" : ""}`}
                    aria-invalid={errors.phone ? "true" : "false"}
                    aria-describedby={errors.phone ? "patient-phone-error" : undefined}
                    value={form.phone}
                    onChange={(e) => update("phone", e.target.value)}
                    placeholder="10-digit mobile"
                  />
                </div>
                {errors.phone ? (
                  <p id="patient-phone-error" className="error-text" role="alert" aria-live="polite">
                    {errors.phone}
                  </p>
                ) : (
                  <p className="text-xs text-ink-subtle">Used by the ANM and helpdesk to call back</p>
                )}
              </div>

              <FormField
                label="Age (completed years)"
                id="patient-age"
                required
                error={errors.age}
              >
                <input
                  type="number"
                  inputMode="numeric"
                  min={15}
                  max={55}
                  value={form.age}
                  onChange={(e) => update("age", e.target.value)}
                  placeholder="e.g. 24"
                />
              </FormField>

              <Select
                label="Village / HWC"
                id="patient-village"
                required
                placeholder={villageOptions.length === 0 ? "Your facility" : "Select a village"}
                options={villageOptions}
                value={form.villageId}
                onChange={(e) => update("villageId", e.target.value)}
                error={errors.villageId}
                hint="Mapped to the local Health & Wellness Sub-Center"
              />
            </PanelBody>
          </Panel>

          <Panel>
            <PanelHeader
              title="Pregnancy"
              description="LMP drives the EDD badge and the follow-up schedule"
              action={<CalendarIcon className="h-4 w-4 text-ink-subtle" />}
            />
            <PanelBody className="space-y-5">
              <div>
                <FormField
                  label="LMP (last menstrual period)"
                  id="patient-lmp"
                  required
                  error={errors.lmp}
                  hint="The EDD and gestational age are calculated from this date"
                >
                  <input
                    type="date"
                    max={new Date().toISOString().slice(0, 10)}
                    value={form.lmp}
                    onChange={(e) => update("lmp", e.target.value)}
                  />
                </FormField>
                {validLmp && edd ? (
                  <div className="mt-2 flex flex-wrap gap-2" aria-live="polite">
                    <span className="badge badge-info">
                      <CalendarIcon className="h-3 w-3" />
                      EDD {format(edd, "d MMM yyyy")}
                    </span>
                    <span className="badge badge-gray">
                      Gestational age {gestationalAgeLabel(validLmp)}
                    </span>
                  </div>
                ) : null}
              </div>

              <Select
                label="Complication"
                id="patient-complication"
                required
                placeholder="Select the HRP complication"
                options={COMPLICATION_OPTIONS}
                value={form.complication}
                onChange={(e) => update("complication", e.target.value as HrpComplication)}
                error={errors.complication}
              />

              <fieldset>
                <legend className="label">Referring or not?</legend>
                <div className="mt-2 grid gap-2 sm:grid-cols-2">
                  <label
                    className={`flex cursor-pointer items-start gap-2.5 rounded border px-3 py-3 transition-colors ${
                      form.referred
                        ? "border-triage-red-solid bg-triage-red-bg"
                        : "border-line bg-surface hover:bg-canvas"
                    }`}
                  >
                    <input
                      type="radio"
                      name="referred"
                      value="yes"
                      checked={form.referred}
                      onChange={() => update("referred", true)}
                      className="mt-0.5 h-4 w-4 text-triage-red-solid focus:ring-triage-red-line"
                    />
                    <span>
                      <span className="block text-sm font-semibold text-ink">
                        Yes — Refer to CHC/FRU
                      </span>
                      <span className="block text-xs text-ink-subtle">
                        Escalates to the Block Nodal HRP Helpdesk and the BHM panel
                      </span>
                    </span>
                  </label>

                  <label
                    className={`flex cursor-pointer items-start gap-2.5 rounded border px-3 py-3 transition-colors ${
                      !form.referred
                        ? "border-primary bg-primary-light"
                        : "border-line bg-surface hover:bg-canvas"
                    }`}
                  >
                    <input
                      type="radio"
                      name="referred"
                      value="no"
                      checked={!form.referred}
                      onChange={() => update("referred", false)}
                      className="mt-0.5 h-4 w-4 text-primary focus:ring-primary-ring"
                    />
                    <span>
                      <span className="block text-sm font-semibold text-ink">
                        No — Routine Field Management
                      </span>
                      <span className="block text-xs text-ink-subtle">
                        Managed at the village HSC cluster
                      </span>
                    </span>
                  </label>
                </div>
              </fieldset>
            </PanelBody>
          </Panel>

          <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
            <Link to="/" className="btn btn-secondary">
              Cancel
            </Link>
            <button
              type="submit"
              className="btn btn-primary btn-lg"
              disabled={createMutation.isPending}
            >
              {createMutation.isPending ? "Saving…" : "Add to HRP register"}
            </button>
          </div>
        </div>

        <aside className="space-y-4">
          <Panel className="bg-primary-light">
            <PanelBody className="space-y-2">
              <h2 className="text-sm font-semibold text-primary-dark">What happens after saving</h2>
              <ul className="space-y-2 text-sm text-ink-muted">
                <li className="flex gap-2">
                  <span
                    aria-hidden="true"
                    className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-primary"
                  />
                  She joins the HRP register for your village cluster.
                </li>
                <li className="flex gap-2">
                  <span
                    aria-hidden="true"
                    className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-primary"
                  />
                  The earliest track — 7-day MO review, next PMSMA, or VHSND — is scheduled for
                  her.
                </li>
                <li className="flex gap-2">
                  <span
                    aria-hidden="true"
                    className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-primary"
                  />
                  Referred cases appear on the Block Nodal helpdesk and BHM panel.
                </li>
              </ul>
            </PanelBody>
          </Panel>

          <Panel>
            <PanelBody className="space-y-2">
              <h2 className="flex items-center gap-2 text-sm font-semibold text-ink">
                <MapPinIcon className="h-4 w-4 text-ink-subtle" />
                Village mapping
              </h2>
              <p className="text-xs leading-relaxed text-ink-subtle">
                The village you pick maps the woman to her Health & Wellness Sub-Center, so follow-up
                lists reach the right ANM.
              </p>
            </PanelBody>
          </Panel>

          <Panel>
            <PanelBody className="space-y-2">
              <h2 className="flex items-center gap-2 text-sm font-semibold text-ink">
                <PhoneIcon className="h-4 w-4 text-ink-subtle" />
                Call-back number
              </h2>
              <p className="text-xs leading-relaxed text-ink-subtle">
                The mobile number is what the ANM and HRP Helpdesk dial when a contact is
                not reachable.
              </p>
            </PanelBody>
          </Panel>

          <Panel>
            <PanelBody className="space-y-2">
              <h2 className="flex items-center gap-2 text-sm font-semibold text-ink">
                <ClipboardIcon className="h-4 w-4 text-ink-subtle" />
                Complication drives risk
              </h2>
              <p className="text-xs leading-relaxed text-ink-subtle">
                Every complication scores her AMBER or above, so no HRP registration is silently
                marked low risk.
              </p>
            </PanelBody>
          </Panel>
        </aside>
      </form>
    </div>
  );
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import {
  AlertTriangleIcon,
  ArrowRightIcon,
  CheckIcon,
  PlusIcon,
  SyncIcon,
} from "../components/ui/Icons";
import { Panel, PanelBody } from "../components/ui/Panel";
import { api } from "../lib/api";
import { buildFollowUpLineList, isBreached } from "../lib/hrp";
import { isOnline, onOnlineChange } from "../utils/sw";

/**
 * First screen for ANM and CHO.
 *
 * The whole screen is one action: register a case. The only other thing on it
 * is the critical instruction strip at the bottom — an urgent follow-up or a
 * sync prompt — because that is the one message a field worker must not miss.
 */
export default function FieldHome() {
  const queryClient = useQueryClient();
  const [online, setOnline] = useState(true);
  const [syncedAt, setSyncedAt] = useState<string | null>(null);

  useEffect(() => {
    setOnline(navigator.onLine);
    return onOnlineChange(setOnline);
  }, []);

  const { data } = useQuery({
    queryKey: ["patients", "field-home"],
    queryFn: () => api.patients.list({ page: 1, limit: 100 }),
    staleTime: 60 * 1000,
  });

  const patients = data?.data ?? [];
  const rows = buildFollowUpLineList(patients, []);
  const urgent = rows.filter(
    (row) => row.status !== "COMPLETE" && (row.riskLevel === "RED" || isBreached(row))
  );
  const pending = rows.filter((row) => row.status !== "COMPLETE").length;

  const syncMutation = useMutation({
    mutationFn: () => api.sync.push({ patients: [], visits: [], referrals: [] }),
    onSuccess: () => {
      const now = new Date();
      localStorage.setItem("lastSyncTime", String(now.getTime()));
      setSyncedAt(format(now, "HH:mm"));
      queryClient.invalidateQueries({ queryKey: ["patients"] });
    },
  });

  return (
    <div className="flex min-h-[calc(100vh-11rem)] flex-col gap-4">
      <header className="min-w-0">
        <p className="text-2xs font-semibold uppercase tracking-wider text-primary">
          {format(new Date(), "EEEE d MMMM")} · Field work
        </p>
        <h1 className="mt-1 text-xl font-semibold tracking-tight text-ink sm:text-2xl">
          Register a high-risk pregnancy
        </h1>
      </header>

      <Link
        to="/patients/new"
