131:       : patient?.followUpScheduledDate
132:         ? new Date(patient.followUpScheduledDate)
133:         : defaultScheduledDate(track, record?.village ?? null, now);
134: 
135:     rows.push({
136:       key: record ? `follow-up-${record.id}` : `patient-${patientId}`,
137:       patientId,
138:       followUpId: record?.id ?? null,
139:       patientName: record?.patientName ?? patient?.name ?? "Unknown woman",
140:       age: record?.patientAge ?? patient?.age ?? 0,
141:       phone: record?.patientPhone ?? patient?.phone ?? null,
142:       ashaPhone: patient?.ashaPhone ?? null,
143:       village: record?.village ?? patient?.address ?? null,
144:       complication: record?.hrpComplication ?? patient?.hrpComplication ?? null,
145:       riskLevel: record?.patientRiskLevel ?? patient?.riskLevel ?? "GREEN",
146:       track,
