197: export function summariseFollowUps(
198:   rows: FollowUpRow[],
199:   now: Date = new Date()
200: ): FollowUpSummary {
201:   const byTrack: Record<HrpFollowUpTrack, TrackSummary> = {
202:     IMMEDIATE_7_DAYS: emptyTrack(),
203:     PMSMA_SESSION: emptyTrack(),
204:     VHSND_COMMUNITY: emptyTrack(),
205:   };
206: 
207:   let pending = 0;
208:   let complete = 0;
209:   let notReachable = 0;
210:   let breached = 0;
211: 
212:   for (const row of rows) {
213:     const track = byTrack[row.track];
214:     track.total += 1;
