49: async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
50:   const headers: Record<string, string> = {
51:     ...(options.headers as Record<string, string>),
52:   };
53: 
54:   // Only send a JSON content type when there is a body. Fastify rejects an
55:   // empty body with a JSON content type, which would break DELETE and any
56:   // other bodyless request.
57:   if (options.body !== undefined && !headers["Content-Type"]) {
58:     headers["Content-Type"] = "application/json";
59:   }
60: 
61:   const token = localStorage.getItem("accessToken");
62:   if (token) headers.Authorization = `Bearer ${token}`;
63: 
64:   const response = await fetch(`${API_BASE}${path}`, {
65:     ...options,
66:     headers,
67:     credentials: "include",
68:   });
69: 
70:   if (response.status === 401) {
71:     const refreshed = await refreshToken();
72:     if (refreshed) {
73:       return request(path, options);
74:     }
75:     localStorage.clear();
76:     window.location.href = "/login";
77:     throw new ApiError(401, null, "Unauthorized");
78:   }
79: 
80:   const data = await response.json().catch(() => null);
81: 
82:   if (!response.ok) {
83:     throw new ApiError(response.status, data, data?.message ?? "Request failed");
84:   }
85: 
86:   return data as T;
87: }
