89: async function refreshToken(): Promise<boolean> {
90:   // The refresh token lives in an httpOnly cookie the browser sends
91:   // automatically. It is never read or written from JavaScript.
92:   try {
93:     const response = await fetch(`${API_BASE}/auth/refresh`, {
94:       method: "POST",
95:       headers: { "Content-Type": "application/json" },
96:       credentials: "include",
97:     });
98: 
99:     if (response.ok) {
100:       const data = await response.json();
101:       if (data.accessToken) {
102:         localStorage.setItem("accessToken", data.accessToken);
103:         return true;
104:       }
105:     }
106:   } catch {
107:     // Network failure during refresh is treated as "not refreshed".
108:   }
109:   return false;
110: }
