253: 
254:     case "patient:write":
255:     case "visit:write":
256:     case "referral:create":
257:     case "sync:push":
258:       return canWriteClinical(actor, target);
259: 
260:     case "patient:archive":
261:     case "audit:read":
262:     case "admin:manage":
263:       return canAdminister(actor, target);
264: 
265:     case "patient:delete":
266:     case "visit:delete":
267:       return deny("ROLE_NOT_PERMITTED");
268: 
269:     case "referral:read":
270:       return canReadReferral(actor, target);
271: 
272:     case "referral:respond":
273:       return canRespondToReferral(actor, target);
274: 
275:     case "alert:acknowledge":
276:       return canAcknowledgeAlert(actor, target);
277: 
278:     case "queue:retry":
279:       return canRetryQueue(actor, target);
280: 
281:     case "followup:manage":
282:       return canManageFollowUp(actor, target);
283: 
284:     case "staff:manage":
