93: export function isPathInSubtree(scopePath: string, targetPath: string): boolean {
94:   if (scopePath.length === 0 || targetPath.length === 0) return false;
95:   return targetPath === scopePath || targetPath.startsWith(`${scopePath}.`);
96: }
