98: export function escapeLikePattern(value: string): string {
99:   return value.replace(/[\\%_]/g, "\\$&");
100: }
101: 
102: export function pathSubtreeLikePattern(path: string): string {
103:   return `${escapeLikePattern(path)}.%`;
104: }
