106: function pathScopePredicate(path: string, column: string): RawBuilder<boolean> {
107:   return sql<boolean>`(${sql.ref(column)} = ${path} OR ${sql.ref(column)} LIKE ${pathSubtreeLikePattern(path)} ESCAPE '\\')`;
108: }
