114: /**
115:  * Referral visibility: an ANM only sees its own outbound referrals, while
116:  * supervisors see referrals touching either endpoint of their subtree. A
117:  * `REFERRAL_NODAL` grant widens that to either endpoint of the grant scope.
118:  */
119: export function referralVisibilityPredicate(
120:   actor: ActorScope,
121:   fromColumn: string,
122:   toColumn: string
123: ): RawBuilder<boolean> {
124:   const conditions: RawBuilder<boolean>[] = [];
125: 
126:   if (actor.role === "ANM") {
127:     conditions.push(sql<boolean>`(${sql.ref(fromColumn)} = ${actor.facilityPath})`);
128:   } else {
129:     conditions.push(pathScopePredicate(actor.facilityPath, fromColumn));
130:     conditions.push(pathScopePredicate(actor.facilityPath, toColumn));
131:   }
132: 
133:   for (const grant of actor.responsibilities) {
134:     if (grant.responsibility !== REFERRAL_NODAL) continue;
135:     conditions.push(pathScopePredicate(grant.scopePath, fromColumn));
136:     conditions.push(pathScopePredicate(grant.scopePath, toColumn));
137:   }
138: 
139:   return conditions.reduce((left, right) => sql<boolean>`(${left} OR ${right})`);
140: }
