142: function buildResponsibilities(
143:   records: readonly ActorResponsibilityRecord[]
144: ): ResponsibilityGrant[] {
145:   const grants: ResponsibilityGrant[] = [];
146: 
147:   for (const record of records) {
148:     if (record.responsibility !== REFERRAL_NODAL) continue;
149:     if (record.scopePath.length === 0) continue;
150: 
151:     grants.push({
152:       responsibility: REFERRAL_NODAL,
153:       scopeFacilityId: record.scopeFacilityId,
154:       scopePath: record.scopePath,
155:     });
156:   }
157: 
158:   return grants;
159: }
