161: export function buildActorScope(
162:   user: ActorUserRecord,
163:   facility: ActorFacilityRecord,
164:   responsibilities: readonly ActorResponsibilityRecord[] = []
165: ): ActorScope {
166:   if (!user.isActive) {
167:     throw new AuthzError("INACTIVE_USER", "User is inactive", { userId: user.id });
168:   }
169: 
170:   if (user.facilityId !== facility.id) {
171:     throw new AuthzError("USER_FACILITY_MISMATCH", "User and facility do not match", {
172:       userId: user.id,
173:       userFacilityId: user.facilityId,
174:       facilityId: facility.id,
175:     });
176:   }
177: 
178:   const role = UserRole.safeParse(user.role);
179:   if (!role.success) {
180:     throw new AuthzError("UNKNOWN_ROLE", "User role is not supported", {
181:       userId: user.id,
182:       role: user.role,
183:     });
184:   }
185: 
186:   if (facility.path.length === 0) {
187:     throw new AuthzError("UNKNOWN_FACILITY", "Facility has no scope path", {
188:       facilityId: facility.id,
189:     });
190:   }
191: 
192:   const level = FacilityLevel.safeParse(facility.level);
193:   if (!level.success) {
194:     throw new AuthzError("UNKNOWN_FACILITY", "Facility level is not supported", {
195:       facilityId: facility.id,
196:       level: facility.level,
197:     });
198:   }
199: 
200:   if (!isFacilityRoleCompatible(role.data, level.data)) {
201:     throw new AuthzError("ROLE_FACILITY_MISMATCH", "Role is not valid for the facility level", {
202:       role: role.data,
203:       level: level.data,
204:       facilityId: facility.id,
205:     });
206:   }
207: 
208:   return {
209:     userId: user.id,
210:     role: role.data,
211:     facilityId: facility.id,
212:     facilityPath: facility.path,
213:     facilityLevel: level.data,
214:     homeFacilityId: facility.id,
215:     homeFacilityPath: facility.path,
216:     homeFacilityLevel: level.data,
217:     responsibilities: buildResponsibilities(responsibilities),
218:   };
219: }
