221: export async function resolveActor(userId: string, lookup: ActorLookup): Promise<ActorScope> {
222:   const user = await lookup.findUser(userId);
223:   if (!user) {
224:     throw new AuthzError("UNKNOWN_USER", "User was not found", { userId });
225:   }
226: 
227:   if (!user.isActive) {
228:     throw new AuthzError("INACTIVE_USER", "User is inactive", { userId });
229:   }
230: 
231:   const [facility, responsibilities] = await Promise.all([
232:     lookup.findFacility(user.facilityId),
233:     lookup.findResponsibilities(userId),
234:   ]);
235: 
236:   if (!facility) {
237:     throw new AuthzError("UNKNOWN_FACILITY", "Actor facility was not found", {
238:       userId,
239:       facilityId: user.facilityId,
240:     });
241:   }
242: 
243:   return buildActorScope(user, facility, responsibilities);
244: }
