246: export async function assertRequestedScope(
247:   actor: ActorScope,
248:   requestedFacilityId: string | null | undefined,
249:   lookup: Pick<ActorLookup, "findFacility">
250: ): Promise<ActorScope> {
251:   if (!requestedFacilityId || requestedFacilityId === actor.facilityId) {
252:     return actor;
253:   }
254: 
255:   const facility = await lookup.findFacility(requestedFacilityId);
256:   if (!facility) {
257:     throw new AuthzError("UNKNOWN_FACILITY", "Requested facility was not found", {
258:       facilityId: requestedFacilityId,
259:     });
260:   }
261: 
262:   if (!isPathInSubtree(actor.facilityPath, facility.path)) {
263:     throw new AuthzError("SCOPE_WIDENING", "Requested facility is outside the actor scope", {
264:       actorFacilityId: actor.facilityId,
265:       requestedFacilityId,
266:     });
267:   }
268: 
269:   const level = FacilityLevel.safeParse(facility.level);
270:   if (!level.success) {
271:     throw new AuthzError("UNKNOWN_FACILITY", "Requested facility level is not supported", {
272:       facilityId: requestedFacilityId,
273:       level: facility.level,
274:     });
275:   }
276: 
277:   return {
278:     ...actor,
279:     facilityId: facility.id,
280:     facilityPath: facility.path,
281:     facilityLevel: level.data,
282:     responsibilities: actor.responsibilities.filter((grant) =>
283:       isPathInSubtree(facility.path, grant.scopePath)
284:     ),
285:   };
286: }
