288: export function createDbActorLookup(database: Kysely<DB>): ActorLookup {
289:   return {
290:     async findUser(userId) {
291:       const row = await database
292:         .selectFrom("users")
293:         .select(["id", "role", "facility_id", "is_active"])
294:         .where("id", "=", userId)
295:         .executeTakeFirst();
296: 
297:       if (!row) return null;
298: 
299:       return {
300:         id: row.id,
301:         role: row.role,
302:         facilityId: row.facility_id,
303:         isActive: row.is_active,
304:       };
305:     },
306: 
307:     async findFacility(facilityId) {
308:       const row = await database
309:         .selectFrom("facilities")
310:         .select(["id", "path", "level"])
311:         .where("id", "=", facilityId)
312:         .executeTakeFirst();
313: 
314:       if (!row) return null;
315: 
316:       return {
317:         id: row.id,
318:         path: row.path,
319:         level: row.level,
320:       };
321:     },
322: 
323:     async findResponsibilities(userId) {
324:       const rows = await database
325:         .selectFrom("responsibilities as responsibility")
326:         .innerJoin("facilities as scope", "scope.id", "responsibility.scope_facility_id")
327:         .select([
328:           "responsibility.responsibility as responsibility",
329:           "responsibility.scope_facility_id as scope_facility_id",
330:           "scope.path as scope_path",
331:         ])
332:         .where("responsibility.user_id", "=", userId)
333:         .execute();
334: 
335:       return rows.map((row) => ({
336:         responsibility: row.responsibility,
337:         scopeFacilityId: row.scope_facility_id,
338:         scopePath: row.scope_path,
339:       }));
340:     },
341:   };
342: }

