1: #!/usr/bin/env node
2: // check-changed-coverage.js
3: // Intersects lcov coverage with the git diff to enforce coverage on the
4: // lines that actually changed (CONSTRAINTS.md requires >= 80%).
5: 
6: import { execSync } from "node:child_process";
7: import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
8: import { dirname, join, relative, resolve } from "node:path";
9: 
10: const MIN_COVERAGE = 80;
11: const COVERAGE_DIRS = [
12:   "packages/shared/coverage",
13:   "packages/server/coverage",
14:   "packages/client/coverage",
15: ];
16: 
17: /** Lines added or modified by the working tree, keyed by repo-relative path. */
18: function getChangedLines() {
19:   const diff = execSync("git diff --unified=0 HEAD", {
20:     encoding: "utf8",
21:     stdio: ["ignore", "pipe", "ignore"],
22:   });
23:   const files = new Map();
24: 
25:   let currentFile = "";
26:   for (const line of diff.split("\n")) {
27:     if (line.startsWith("+++ b/")) {
28:       currentFile = line.slice(6);
29:       if (!files.has(currentFile)) files.set(currentFile, new Set());
30:     } else if (line.startsWith("@@") && currentFile) {
31:       const match = line.match(/@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/);
32:       if (match) {
33:         const start = Number.parseInt(match[1], 10);
34:         const count = match[2] ? Number.parseInt(match[2], 10) : 1;
35:         const set = files.get(currentFile);
36:         for (let i = 0; i < count; i += 1) set.add(start + i);
37:       }
38:     }
39:   }
40: 
41:   return files;
42: }
43: 
44: /** Every lcov record found in the workspace, keyed by absolute source path. */
45: function readLcovFiles() {
46:   const records = new Map();
47: 
48:   for (const dir of COVERAGE_DIRS) {
49:     const lcovPath = resolve(dir, "lcov.info");
50:     if (!existsSync(lcovPath)) continue;
51: 
52:     // lcov records source paths relative to the package root, not to the
53:     // coverage directory (e.g. "src/rules.ts"). The coverage directory sits
54:     // inside the package, so the package root is its parent.
55:     const packageRoot = resolve(dir, "..");
56:     let currentFile = "";
57:     let currentLineMap = new Map();
58: 
59:     for (const line of readFileSync(lcovPath, "utf8").split("\n")) {
60:       if (line.startsWith("SF:")) {
61:         currentFile = resolve(packageRoot, line.slice(3));
62:         currentLineMap = new Map();
63:         records.set(currentFile, currentLineMap);
64:       } else if (line.startsWith("DA:")) {
65:         // Format: DA:<line number>,<execution count>[,<checksum>]
66:         const [lineNum, hits] = line.slice(3).split(",");
67:         currentLineMap.set(Number.parseInt(lineNum, 10), Number.parseInt(hits, 10));
68:       } else if (line === "end_of_record") {
69:         currentFile = "";
70:       }
71:     }
72:   }
73: 
74:   return records;
75: }
76: 
77: /** Maps an absolute source path to its repo-relative path. */
78: function toRepoPath(absolutePath) {
79:   const root = process.cwd();
80:   const normalized = absolutePath.replace(/\\/g, "/");
81:   const normalizedRoot = root.replace(/\\/g, "/");
82:   if (normalized.startsWith(normalizedRoot)) {
83:     return normalized.slice(normalizedRoot.length + 1);
84:   }
85:   return relative(root, absolutePath).replace(/\\/g, "/");
86: }
87: 
88: /**
89:  * Files that are excluded from the changed-line coverage bar.
90:  *
91:  * These are build configuration, process entrypoints, and CLI scripts that are
92:  * exercised end-to-end (Docker healthcheck, `npm run db:migrate`, `db:seed`,
93:  * the service worker registration) rather than unit-tested. Application
94:  * behaviour stays subject to the 80% bar.
95:  */
96: const EXCLUDED_PATTERNS = [
97:   /(^|\/)[a-z.-]*\.config\.(ts|js|mjs|tsx)$/i,
98:   /(^|\/)vitest\.setup\./,
99:   /\.d\.ts$/,
100:   /\.test\.(ts|tsx)$/,
101:   /\.spec\.(ts|tsx)$/,
102:   /^packages\/server\/src\/index\.ts$/,
103:   /^packages\/server\/src\/db\/(migrate|seed)\.ts$/,
104:   /^packages\/client\/src\/main\.tsx$/,
105:   /^packages\/client\/src\/utils\/sw\.ts$/,
106: ];
107: 
108: /** Returns true when a repo-relative path is outside the coverage bar. */
109: function isExcluded(repoPath) {
110:   return EXCLUDED_PATTERNS.some((pattern) => pattern.test(repoPath));
111: }
112: 
113: function main() {
114:   const changedLines = getChangedLines();
115:   const coverage = readLcovFiles();
116: 
117:   // Repo-relative path -> line -> hit count
118:   const byRepoPath = new Map();
119:   for (const [absolutePath, lineMap] of coverage) {
120:     byRepoPath.set(toRepoPath(absolutePath), lineMap);
121:   }
122: 
123:   let totalChanged = 0;
124:   let coveredChanged = 0;
125:   const uncovered = [];
126:   const filesWithoutCoverage = [];
127:   const perFile = [];
128: 
129:   for (const [file, lines] of changedLines) {
130:     if (isExcluded(file)) continue;
131: 
132:     const cov = byRepoPath.get(file);
133:     if (!cov) {
134:       // No coverage data for this file. Report it so a new untested module is
135:       // visible instead of silently skipped.
136:       if (/\.(ts|tsx)$/.test(file)) {
137:         filesWithoutCoverage.push(file);
138:       }
139:       continue;
140:     }
141: 
142:     let fileHits = 0;
143:     for (const line of lines) {
144:       const hits = cov.get(line);
145:       // Lines that never appear in the lcov data are not executable (comments,
146:       // blank lines, type-only declarations). Counting them would make the bar
147:       // impossible to reach for any change that adds documentation.
148:       if (hits === undefined) continue;
149: 
150:       totalChanged += 1;
151:       if (hits > 0) {
152:         fileHits += 1;
153:         coveredChanged += 1;
154:       } else {
155:         uncovered.push(`${file}:${line}`);
156:       }
157:     }
158:     if (lines.size > 0) perFile.push({ file, changed: lines.size, covered: fileHits });
159:   }
160: 
161:   const pct = totalChanged > 0 ? Math.round((coveredChanged / totalChanged) * 100) : 100;
162: 
163:   console.log(`Changed lines:        ${totalChanged}`);
164:   console.log(`Covered changed lines: ${coveredChanged}`);
165:   console.log(`Coverage:              ${pct}%`);
166: 
167:   if (perFile.length > 0) {
168:     perFile.sort((a, b) => b.changed - a.changed);
169:     console.log("\nPer file (changed / covered):");
170:     for (const { file, changed, covered } of perFile) {
171:       console.log(`  ${String(covered).padStart(4)} / ${String(changed).padStart(4)}  ${file}`);
172:     }
173:   }
174: 
175:   if (filesWithoutCoverage.length > 0) {
176:     console.log(`\nChanged files with no coverage data (${filesWithoutCoverage.length}):`);
177:     for (const file of filesWithoutCoverage.slice(0, 20)) console.log(`  ${file}`);
178:   }
179: 
180:   if (pct < MIN_COVERAGE) {
181:     console.error(`\nUNCOVERED CHANGED LINES (${uncovered.length}):`);
182:     for (const line of uncovered.slice(0, 50)) console.error(`  ${line}`);
183:     if (uncovered.length > 50) console.error(`  ... and ${uncovered.length - 50} more`);
184:     console.error(`\nCoverage on changed lines must be >= ${MIN_COVERAGE}%`);
185:     process.exit(1);
186:   }
187: 
188:   console.log(`\nCoverage on changed lines >= ${MIN_COVERAGE}%`);
189: }
190: 
191: main();

