import {
  type HrpFollowUpStatus,
  HRP_FOLLOW_UP_TRACKS,
  getHrpComplicationLabel,
  getHrpStatusBadge,
  getHrpStatusLabel,
} from "@hrp/shared";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import { Link } from "react-router-dom";
import { EmptyState } from "../ui/EmptyState";
import {
  CalendarIcon,
  CheckIcon,
  ClipboardIcon,
  PhoneIcon,
  SyncIcon,
} from "../ui/Icons";
import { PageHeader } from "../ui/PageHeader";
import { Panel, PanelBody, PanelHeader } from "../ui/Panel";
import { StatTile } from "../ui/Stat";
import { api } from "../../lib/api";
import {
  type FollowUpRow,
  attributionLabel,
  buildFollowUpLineList,
  formatShortDate,
  summariseFollowUps,
} from "../../lib/hrp";

interface UpdateStatusVariables {
  followUpId: string;
  status: HrpFollowUpStatus;
}

/**
 * Field panel for ANM and CHO.
 *
 * Only lists pushed to this worker by the block appear here. The three tracks
 * stay separate because they happen at different places — CHC for the 7-day MO
 * review, PHC for PMSMA, and the village for VHSND — and a field worker plans
 * her day by location, not by a single merged queue.
 */
export default function FieldFollowUpPanel() {
  const queryClient = useQueryClient();

  const { data: user } = useQuery({
    queryKey: ["auth", "me"],
    queryFn: () => api.auth.me(),
    staleTime: 5 * 60 * 1000,
    retry: false,
  });

  const { data: recordsData, isLoading: recordsLoading, isError } = useQuery({
    queryKey: ["hrp", "follow-ups", "field-panel"],
    queryFn: () => api.hrp.followUps.list({ page: 1, limit: 100 }),
  });

  const { data: patientsData, isLoading: patientsLoading } = useQuery({
    queryKey: ["patients", "follow-ups"],
    queryFn: () => api.hrp.patients.list({ page: 1, limit: 100 }),
  });

  const records = recordsData?.data ?? [];
  const patients = patientsData?.data ?? [];
  const allRows = buildFollowUpLineList(patients, records);

  // A row belongs to this worker when the block dispatched it to her, when she
  // closed it, or when it is her own registration that has not been dispatched
  // yet. Rows assigned to another tier stay out of her phone.
  const rows = allRows.filter((row) => {
    if (!user) return true;
    if (!row.followUpId) return true;
    if (row.assignedToName === user.name) return true;
    if (row.completedByName === user.name) return true;
    return !row.assignedToName;
  });

  const summary = summariseFollowUps(rows);
  const loading = recordsLoading || patientsLoading;

  const statusMutation = useMutation({
    mutationFn: ({ followUpId, status }: UpdateStatusVariables) =>
      api.hrp.followUps.update(followUpId, { status }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["hrp", "follow-ups"] });
      queryClient.invalidateQueries({ queryKey: ["patients"] });
    },
  });

  const setStatus = (row: FollowUpRow, status: HrpFollowUpStatus) => {
    if (!row.followUpId) return;
    statusMutation.mutate({ followUpId: row.followUpId, status });
  };

  return (
    <div className="space-y-5">
      <PageHeader
        eyebrow="Field work"
        title="Follow-up to be done"
        description="Lists pushed to you by the block, one card per contact"
        actions={
          <Link to="/patients" className="btn btn-secondary">
            <ClipboardIcon className="h-4 w-4" />
            Open register
          </Link>
        }
      />

      <div className="grid grid-cols-3 gap-2.5 sm:gap-3">
        <StatTile
          label="Complete"
          value={summary.complete}
          hint="Closed on this device"
          tone="green"
          icon={<CheckIcon className="h-4 w-4" />}
        />
        <StatTile
          label="Pending"
          value={summary.pending}
          hint={summary.breached > 0 ? `${summary.breached} past the window` : "Inside the window"}
          tone={summary.breached > 0 ? "red" : "amber"}
          icon={<CalendarIcon className="h-4 w-4" />}
        />
        <StatTile
          label="Not reachable"
          value={summary.notReachable}
          hint="Retry after a failed call"
          icon={<PhoneIcon className="h-4 w-4" />}
        />
      </div>

      {statusMutation.isError ? (
        <div
          className="rounded border border-triage-red-line bg-triage-red-bg px-4 py-3"
          role="alert"
        >
          <p className="text-sm font-medium text-triage-red">
            Could not update that follow-up. Check the connection and try again.
          </p>
        </div>
      ) : null}

      {loading ? (
        <div className="space-y-3" aria-busy="true" aria-label="Loading follow-ups">
          {[0, 1, 2].map((index) => (
            <div key={index} className="h-36 animate-pulse rounded-lg bg-line-soft" />
          ))}
        </div>
      ) : isError ? (
        <Panel>
          <EmptyState
            title="Follow-ups could not load"
            description="The block list is unavailable right now. Pull to refresh when the network returns."
          />
        </Panel>
      ) : rows.length === 0 ? (
        <Panel>
          <EmptyState
            title="No follow-up list assigned yet"
            description="When the Block Nodal officer pushes a list to you, it appears here with the three contact tracks."
            action={
              <Link to="/patients/new" className="btn btn-primary btn-sm">
                Add an HRP case
              </Link>
            }
          />
        </Panel>
      ) : (
        <div className="space-y-4">
          {HRP_FOLLOW_UP_TRACKS.map((track) => {
            const trackRows = rows.filter((row) => row.track === track.value);
            return (
              <Panel key={track.value} aria-labelledby={`track-${track.value}`}>
                <PanelHeader
                  id={`track-${track.value}`}
                  title={
                    <span className="flex items-center gap-2">
                      {track.label}
                      <span className="badge badge-gray">{trackRows.length}</span>
                    </span>
                  }
                  description={track.description}
                />
                {trackRows.length === 0 ? (
                  <PanelBody>
                    <p className="text-sm text-ink-subtle">Nothing scheduled on this track.</p>
                  </PanelBody>
                ) : (
                  <ul className="divide-y divide-line-soft">
                    {trackRows.map((row) => (
                      <li key={row.key}>
                        <FieldFollowUpCard
                          row={row}
                          pending={statusMutation.isPending}
                          onStatus={setStatus}
                        />
                      </li>
                    ))}
                  </ul>
                )}
              </Panel>
            );
          })}
        </div>
      )}

      <p className="flex items-center gap-1.5 text-xs text-ink-subtle">
        <SyncIcon className="h-3.5 w-3.5" />
        Updates save immediately and sync to the block line list.
      </p>
    </div>
  );
}

function FieldFollowUpCard({
  row,
  pending,
  onStatus,
}: {
  row: FollowUpRow;
  pending: boolean;
  onStatus: (row: FollowUpRow, status: HrpFollowUpStatus) => void;
}) {
  const motherPhone = row.phone?.replace(/\D/g, "");
  const ashaPhone = row.ashaPhone?.replace(/\D/g, "");

  return (
    <article className="px-4 py-3 sm:px-5">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <Link
            to={`/patients/${row.patientId}`}
            className="block truncate text-sm font-semibold text-ink hover:text-primary hover:underline"
          >
            {row.patientName}
          </Link>
          <p className="tnum mt-0.5 text-2xs text-ink-subtle">
            {row.age} yrs
            {row.village ? ` · ${row.village}` : ""} · due {formatShortDate(row.scheduledDate)}
          </p>
          {row.complication ? (
            <p className="mt-1 text-2xs font-medium text-triage-red">
              {getHrpComplicationLabel(row.complication)}
            </p>
          ) : null}
        </div>
        <span className={`badge shrink-0 ${getHrpStatusBadge(row.status)}`}>
          {getHrpStatusLabel(row.status)}
        </span>
      </div>

      {row.status === "NOT_REACHABLE" ? (
        <p className="mt-2 rounded bg-canvas px-2.5 py-1.5 text-2xs text-ink-muted">
          Not reachable
          {row.lastAttemptAt
            ? ` · last attempt ${format(row.lastAttemptAt, "d MMM, HH:mm")}`
            : " · no attempt time recorded"}
        </p>
      ) : null}

      {row.status === "COMPLETE" ? (
        <p className="mt-2 text-2xs font-medium text-triage-green">{attributionLabel(row)}</p>
      ) : (
        <div className="mt-3 flex flex-wrap gap-2">
          <button
            type="button"
            className="btn btn-success btn-sm"
            onClick={() => onStatus(row, "COMPLETE")}
            disabled={pending || !row.followUpId}
            aria-label={`Mark complete for ${row.patientName}`}
          >
            <CheckIcon className="h-3.5 w-3.5" />
            Mark complete
          </button>
          <button
            type="button"
            className="btn btn-secondary btn-sm"
            onClick={() => onStatus(row, "NOT_REACHABLE")}
            disabled={pending || !row.followUpId}
            aria-label={`Mark not reachable for ${row.patientName}`}
          >
            Not reachable
          </button>
          {motherPhone ? (
            <a href={`tel:+91${motherPhone}`} className="btn btn-secondary btn-sm">
              <PhoneIcon className="h-3.5 w-3.5" />
              Call mother
            </a>
          ) : null}
          {ashaPhone ? (
            <a href={`tel:+91${ashaPhone}`} className="btn btn-secondary btn-sm">
              <PhoneIcon className="h-3.5 w-3.5" />
              Call ASHA Sangini
            </a>
          ) : null}
        </div>
      )}

      {!row.followUpId ? (
        <p className="mt-2 text-2xs text-triage-amber">
          Waiting for the block to dispatch this contact before it can be closed.
        </p>
      ) : null}
    </article>
  );
}

import {
  type HrpFollowUpStatus,
  type HrpFollowUpTrack,
  HRP_FOLLOW_UP_STATUSES,
  HRP_FOLLOW_UP_TRACKS,
  getHrpComplicationLabel,
  getHrpStatusBadge,
  getHrpStatusLabel,
  getHrpTrackLabel,
} from "@hrp/shared";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { EmptyState } from "../ui/EmptyState";
import { SearchIcon } from "../ui/Icons";
import { PageHeader } from "../ui/PageHeader";
import { Panel, PanelHeader } from "../ui/Panel";
import { SegmentedControl } from "../ui/SegmentedControl";
import { StatTile } from "../ui/Stat";
import { api } from "../../lib/api";
import {
  type FollowUpRow,
  attributionLabel,
  buildFollowUpLineList,
  formatShortDate,
  summariseFollowUps,
} from "../../lib/hrp";

type StatusFilter = HrpFollowUpStatus | "ALL";
type TrackFilter = HrpFollowUpTrack | "ALL";

interface UpdateStatusVariables {
  followUpId: string;
  status: HrpFollowUpStatus;
}

/**
 * Block and district shared line list.
 *
 * Every woman is one row, regardless of who owns the contact, so the block can
 * see the whole cohort in one place. The status dropdown writes straight to the
 * follow-up record, which stamps the acting user as the completer and leaves an
 * audit trail on the row.
 */
export default function NodalFollowUpPanel() {
  const queryClient = useQueryClient();
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("ALL");
  const [trackFilter, setTrackFilter] = useState<TrackFilter>("ALL");
  const [villageFilter, setVillageFilter] = useState("ALL");
  const [search, setSearch] = useState("");

  const { data: recordsData, isLoading: recordsLoading, isError } = useQuery({
    queryKey: ["hrp", "follow-ups", "nodal-panel"],
    queryFn: () => api.hrp.followUps.list({ page: 1, limit: 100 }),
  });

  const { data: patientsData, isLoading: patientsLoading } = useQuery({
    queryKey: ["patients", "follow-ups"],
    queryFn: () => api.hrp.patients.list({ page: 1, limit: 100 }),
  });

  const records = recordsData?.data ?? [];
  const patients = patientsData?.data ?? [];
  const rows = buildFollowUpLineList(patients, records);
  const summary = summariseFollowUps(rows);

  const villages = useMemo(
    () =>
      [...new Set(rows.map((row) => row.village).filter((value): value is string => Boolean(value)))]
        .sort((a, b) => a.localeCompare(b))
        .map((village) => ({ value: village, label: village })),
    [rows]
  );

  const visible = rows.filter((row) => {
    if (statusFilter !== "ALL" && row.status !== statusFilter) return false;
    if (trackFilter !== "ALL" && row.track !== trackFilter) return false;
    if (villageFilter !== "ALL" && row.village !== villageFilter) return false;
    if (search.trim()) {
      const term = search.trim().toLowerCase();
      const matches =
        row.patientName.toLowerCase().includes(term) ||
        (row.village ?? "").toLowerCase().includes(term) ||
        (row.phone ?? "").includes(term);
      if (!matches) return false;
    }
    return true;
  });

  const loading = recordsLoading || patientsLoading;

  const statusMutation = useMutation({
    mutationFn: ({ followUpId, status }: UpdateStatusVariables) =>
      api.hrp.followUps.update(followUpId, { status }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["hrp", "follow-ups"] });
      queryClient.invalidateQueries({ queryKey: ["patients"] });
    },
  });

  const setStatus = (row: FollowUpRow, status: HrpFollowUpStatus) => {
    if (!row.followUpId) return;
    statusMutation.mutate({ followUpId: row.followUpId, status });
  };

  return (
    <div className="space-y-5">
      <PageHeader
        eyebrow="Oversight"
        title="Follow-up to be done"
        description="The shared block line list, with attribution for every contact"
        actions={
          <Link to="/" className="btn btn-secondary">
            Back to dashboard
          </Link>
        }
      />

      <div className="grid grid-cols-2 gap-2.5 sm:gap-3 lg:grid-cols-4">
        <StatTile label="In the line list" value={summary.total} hint="Women with a contact" />
        <StatTile
          label="Pending"
          value={summary.pending}
          hint={summary.breached > 0 ? `${summary.breached} past the window` : "Inside the window"}
          tone={summary.breached > 0 ? "red" : "amber"}
        />
        <StatTile label="Complete" value={summary.complete} hint="Closed with attribution" tone="green" />
        <StatTile
          label="Compliance"
          value={`${summary.complianceRate}%`}
          hint="Complete ÷ line list"
          tone="primary"
          compact
        />
      </div>

      {statusMutation.isError ? (
        <div
          className="rounded border border-triage-red-line bg-triage-red-bg px-4 py-3"
          role="alert"
        >
          <p className="text-sm font-medium text-triage-red">
            Could not save that status change. The audit entry was not written.
          </p>
        </div>
      ) : null}

      <Panel aria-labelledby="line-list-heading">
        <PanelHeader
          id="line-list-heading"
          title="All women"
          description={`${visible.length} of ${rows.length} rows match the filters`}
          action={
            <SegmentedControl
              label="Filter by follow-up status"
              value={statusFilter}
              onChange={setStatusFilter}
              options={[
                { value: "ALL", label: "All", count: summary.total },
                { value: "PENDING", label: "Pending", count: summary.pending },
                { value: "COMPLETE", label: "Complete", count: summary.complete },
                {
                  value: "NOT_REACHABLE",
                  label: "Not reachable",
                  count: summary.notReachable,
                },
              ]}
            />
          }
        />

        <div className="flex flex-col gap-2 border-b border-line-soft bg-canvas px-4 py-3 sm:flex-row sm:items-center sm:px-5">
          <label className="relative min-w-0 flex-1">
            <span className="sr-only">Search women by name, village or phone</span>
            <SearchIcon className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-ink-subtle" />
            <input
              type="search"
              className="input min-h-control pl-9"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Search name, village or phone"
            />
          </label>
          <select
            className="input min-h-control w-full py-1.5 sm:w-auto"
            aria-label="Filter by track"
            value={trackFilter}
            onChange={(event) => setTrackFilter(event.target.value as TrackFilter)}
          >
            <option value="ALL">All tracks</option>
            {HRP_FOLLOW_UP_TRACKS.map((track) => (
              <option key={track.value} value={track.value}>
                {track.shortLabel} — {track.label}
              </option>
            ))}
          </select>
          <select
            className="input min-h-control w-full py-1.5 sm:w-auto"
            aria-label="Filter by village or sub-center"
            value={villageFilter}
            onChange={(event) => setVillageFilter(event.target.value)}
          >
            <option value="ALL">All villages</option>
            {villages.map((village) => (
              <option key={village.value} value={village.value}>
                {village.label}
              </option>
            ))}
          </select>
        </div>

        {loading ? (
          <div className="space-y-2 p-3 sm:p-4" aria-busy="true" aria-label="Loading line list">
            {[0, 1, 2, 3, 4].map((index) => (
              <div key={index} className="h-14 animate-pulse rounded bg-line-soft" />
            ))}
          </div>
        ) : isError ? (
          <EmptyState
            title="Line list could not load"
            description="The block register is unavailable. It will reappear when the server responds."
          />
        ) : visible.length === 0 ? (
          <EmptyState
            title="No follow-ups match these filters"
            description="Clear the status, track or village filter to see the rest of the block."
          />
        ) : (
          <>
            <ul className="divide-y divide-line-soft xl:hidden">
              {visible.map((row) => (
                <li key={row.key} className="px-4 py-3 sm:px-5">
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <Link
                        to={`/patients/${row.patientId}`}
                        className="block truncate text-sm font-semibold text-ink hover:text-primary hover:underline"
                      >
                        {row.patientName}
                      </Link>
                      <p className="tnum mt-0.5 text-2xs text-ink-subtle">
                        {row.age} yrs · {row.village ?? "Village not recorded"}
                      </p>
                      <p className="mt-0.5 text-2xs text-ink-muted">
                        {getHrpTrackLabel(row.track)} · due {formatShortDate(row.scheduledDate)}
                      </p>
                    </div>
                    <span className={`badge shrink-0 ${getHrpStatusBadge(row.status)}`}>
                      {getHrpStatusLabel(row.status)}
                    </span>
                  </div>
                  {row.complication ? (
                    <p className="mt-1 text-2xs font-medium text-triage-red">
                      {getHrpComplicationLabel(row.complication)}
                    </p>
                  ) : null}
                  <p className="mt-2 text-2xs text-ink-subtle">{attributionLabel(row)}</p>
                  <div className="mt-2 flex items-center gap-2">
                    <label className="flex-1">
                      <span className="sr-only">Status for {row.patientName}</span>
                      <select
                        className="input min-h-control py-1.5"
                        value={row.status}
                        disabled={!row.followUpId || statusMutation.isPending}
                        onChange={(event) =>
                          setStatus(row, event.target.value as HrpFollowUpStatus)
                        }
                      >
                        {HRP_FOLLOW_UP_STATUSES.map((status) => (
                          <option key={status.value} value={status.value}>
                            {status.label}
                          </option>
                        ))}
                      </select>
                    </label>
                    <Link
                      to={`/patients/${row.patientId}`}
                      className="btn btn-secondary btn-sm"
                      aria-label={`Open record for ${row.patientName}`}
                    >
                      Open
                    </Link>
                  </div>
                </li>
              ))}
            </ul>

            <div className="table-container hidden xl:block">
              <table className="table">
                <thead>
                  <tr>
                    <th scope="col">Woman</th>
                    <th scope="col">Village / sub-center</th>
                    <th scope="col">Track</th>
                    <th scope="col">Attribution</th>
                    <th scope="col">Due</th>
                    <th scope="col">Last update</th>
                    <th scope="col">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {visible.map((row) => (
                    <tr key={row.key}>
                      <td>
                        <Link
                          to={`/patients/${row.patientId}`}
                          className="font-medium text-ink hover:text-primary hover:underline"
                        >
                          {row.patientName}
                        </Link>
                        <p className="tnum text-2xs text-ink-subtle">{row.age} yrs</p>
                      </td>
                      <td className="text-ink-muted">{row.village ?? "—"}</td>
                      <td className="text-ink-muted">{getHrpTrackLabel(row.track)}</td>
                      <td className="max-w-64 text-2xs text-ink-muted">{attributionLabel(row)}</td>
                      <td className="tnum whitespace-nowrap text-ink-muted">
                        {format(row.scheduledDate, "d MMM yyyy")}
                      </td>
                      <td className="tnum whitespace-nowrap text-2xs text-ink-subtle">
                        {row.lastAttemptAt ? format(row.lastAttemptAt, "d MMM, HH:mm") : "—"}
                      </td>
                      <td>
                        <select
                          className="input min-h-control w-auto py-1.5"
                          aria-label={`Follow-up status for ${row.patientName}`}
                          value={row.status}
                          disabled={!row.followUpId || statusMutation.isPending}
                          onChange={(event) =>
                            setStatus(row, event.target.value as HrpFollowUpStatus)
                          }
                        >
                          {HRP_FOLLOW_UP_STATUSES.map((status) => (
                            <option key={status.value} value={status.value}>
                              {status.label}
                            </option>
                          ))}
                        </select>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
      </Panel>
    </div>
  );
}

import FieldFollowUpPanel from "../components/follow-ups/FieldFollowUpPanel";
import NodalFollowUpPanel from "../components/follow-ups/NodalFollowUpPanel";
import { useIsFieldRole } from "../lib/session";

/**
 * `/follow-ups` is one route with two audiences.
 *
 * ANM and CHO get the personal three-track panel. Block and district staff get
 * the shared line list with attribution and the status audit dropdown.
 */
export default function FollowUpsPage() {
  const fieldRole = useIsFieldRole();
  return fieldRole ? <FieldFollowUpPanel /> : <NodalFollowUpPanel />;
}

import {
  type HrpFollowUpTrack,
  HRP_FOLLOW_UP_TRACKS,
  getHrpTrackShortLabel,
} from "@hrp/shared";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { format } from "date-fns";
import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { EmptyState } from "../components/ui/EmptyState";
import {
  ActivityIcon,
  AlertTriangleIcon,
  ArrowRightIcon,
  CalendarIcon,
  CheckIcon,
  ListChecksIcon,
  SyncIcon,
  UsersIcon,
} from "../components/ui/Icons";
import { PageHeader } from "../components/ui/PageHeader";
import { Panel, PanelBody, PanelHeader } from "../components/ui/Panel";
import { StatTile } from "../components/ui/Stat";
import { api } from "../lib/api";
import {
  buildFollowUpLineList,
  formatShortDate,
  summariseFollowUps,
} from "../lib/hrp";
import { useIsNodalRole } from "../lib/session";
import { isOnline, onOnlineChange } from "../utils/sw";

function lastSyncLabel(): string | null {
  const raw = localStorage.getItem("lastSyncTime");
  if (!raw) return null;
  const value = Number(raw);
  if (!Number.isFinite(value)) return null;
  return format(new Date(value), "d MMM, HH:mm");
}

/**
 * Block dashboard for the Block Nodal officer, district officer and helpdesk.
 *
 * The counters, the three-track triangulation and the dispatch box all read the
 * same line list as `/follow-ups`, so a number on this screen can always be
 * traced to the rows that produced it.
 */
export default function NodalDashboard() {
  const queryClient = useQueryClient();
  const nodalRole = useIsNodalRole();
  const [online, setOnline] = useState(true);
  const [syncedAt, setSyncedAt] = useState<string | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [assigneeId, setAssigneeId] = useState("");
  const [track, setTrack] = useState<HrpFollowUpTrack>("IMMEDIATE_7_DAYS");

  useEffect(() => {
    setOnline(navigator.onLine);
    setSyncedAt(lastSyncLabel());
    return onOnlineChange(setOnline);
  }, []);

  const { data: recordsData, isLoading: recordsLoading, isError } = useQuery({
    queryKey: ["hrp", "follow-ups", "dashboard"],
    queryFn: () => api.hrp.followUps.list({ page: 1, limit: 100 }),
  });

  const { data: patientsData, isLoading: patientsLoading } = useQuery({
    queryKey: ["hrp", "patients", "dashboard"],
    queryFn: () => api.hrp.patients.list({ page: 1, limit: 100 }),
  });

  const { data: staffData } = useQuery({
    queryKey: ["staff", "assignable"],
    queryFn: () => api.staff.list(),
    enabled: nodalRole,
    retry: false,
  });

  const records = recordsData?.data ?? [];
  const patients = patientsData?.data ?? [];
  const rows = buildFollowUpLineList(patients, records);
  const summary = summariseFollowUps(rows);

  const totalHrps = patientsData?.total ?? patients.length;
  const pendingRows = rows.filter((row) => row.status !== "COMPLETE");
  const assignable = (staffData?.data ?? []).filter(
    (member) => member.isActive && (member.role === "ANM" || member.role === "CHO")
  );

  const allPendingSelected =
    pendingRows.length > 0 && pendingRows.every((row) => selected.has(row.patientId));

  const toggleSelected = (patientId: string) => {
    setSelected((current) => {
      const next = new Set(current);
      if (next.has(patientId)) next.delete(patientId);
      else next.add(patientId);
      return next;
    });
  };

  const toggleAll = () => {
    setSelected(allPendingSelected ? new Set() : new Set(pendingRows.map((row) => row.patientId)));
  };

  const dispatchMutation = useMutation({
    mutationFn: () =>
      api.hrp.followUps.dispatch({
        patientIds: [...selected],
        assignedToUserId: assigneeId,
        track,
      }),
    onSuccess: () => {
      setSelected(new Set());
      queryClient.invalidateQueries({ queryKey: ["hrp", "follow-ups"] });
      queryClient.invalidateQueries({ queryKey: ["patients"] });
    },
  });

  const loading = recordsLoading || patientsLoading;
  const dispatchDisabled =
    !nodalRole || selected.size === 0 || !assigneeId || dispatchMutation.isPending;

  const nextPmsma = useMemo(() => formatShortDate(summary.nextPmsmaDate), [summary.nextPmsmaDate]);

  return (
    <div className="space-y-5">
      <PageHeader
        eyebrow={`${format(new Date(), "EEEE d MMMM")} · Araria block`}
        title="Block dashboard"
        description="High-risk pregnancies, follow-up compliance and dispatch in one view"
        actions={
          <Link to="/follow-ups" className="btn btn-primary">
            <ListChecksIcon className="h-4 w-4" />
            Open line list
          </Link>
        }
      />

      <Panel className={online ? "bg-surface" : "border-triage-amber-line bg-triage-amber-bg"}>
        <PanelBody className="flex flex-wrap items-center gap-3 py-3">
          <span
            aria-hidden="true"
            className={`h-2 w-2 shrink-0 rounded-full ${
              online ? "bg-triage-green-solid" : "bg-triage-amber-solid"
            }`}
          />
          <div className="min-w-0 flex-1">
            <p className="text-sm font-semibold text-ink">
              {online ? "Live sync · normal" : "Offline · showing the last synced block data"}
            </p>
            <p className="text-2xs text-ink-subtle">
              {syncedAt
                ? `Last field sync ${syncedAt}. The line list refreshes automatically.`
                : "No field sync recorded on this device yet."}
            </p>
          </div>
          <span className={`badge ${online ? "badge-green" : "badge-amber"}`}>
            <SyncIcon className="h-3 w-3" />
            {online ? "Live" : "Offline"}
          </span>
        </PanelBody>
      </Panel>

      {isError ? (
        <div
          className="rounded border border-triage-red-line bg-triage-red-bg px-4 py-3"
          role="alert"
        >
